<script setup>
import WorldScene from '../components/WorldScene.vue'
import { computed, ref } from 'vue'
import { Play, Pause, RefreshCw } from 'lucide-vue-next'
import { useI18n } from '../i18n'
const props = defineProps({ worlds: Array, activeWorld: Object, wallet: Object, models: Array, loading: Boolean })
const emit = defineEmits(['select-world', 'toggle-world', 'tutorial'])
const soupTotal = computed(() => props.wallet?.bio_soup?.reduce((sum, item) => sum + item.amount, 0) || 0)
const hasWorlds = computed(() => props.worlds?.length > 0)
const createBusy = ref(false)
const { t } = useI18n()
async function createTutorial() { createBusy.value = true; emit('tutorial'); createBusy.value = false }
</script>
<template><section class="content"><div class="page-intro"><div><span class="eyebrow cyan-text">{{ t('labels.worldEyebrow') }}</span><h2>{{ t('nav.world') }}<span v-if="activeWorld" class="pulse"></span></h2><p>{{ t('world.subtitle') }}</p></div><div class="world-switcher" v-if="hasWorlds"><select :value="activeWorld?.id" @change="emit('select-world', $event.target.value)"><option v-for="world in worlds" :key="world.id" :value="world.id">{{ world.name }}</option></select><button class="ghost-btn" @click="emit('toggle-world')"><Pause v-if="activeWorld?.status === 'active'" :size="15" /> <Play v-else :size="15" /> {{ activeWorld?.status === 'active' ? t('world.pause') : t('world.resume') }}</button></div></div><div v-if="loading" class="empty-state">{{ t('world.loading') }}</div><div v-else-if="!hasWorlds" class="empty-state"><h3>{{ t('world.empty') }}</h3><p>{{ t('world.emptyHint') }}</p><button class="primary-btn" :disabled="createBusy" @click="createTutorial"><RefreshCw :size="15" /> {{ t('world.tutorial') }}</button></div><template v-else><div class="metrics"><div class="metric-card"><span>{{ t('world.models') }}</span><strong>{{ models?.length || 0 }}</strong><small>{{ t('world.modelApi') }}</small></div><div class="metric-card"><span>{{ t('world.worldCount') }}</span><strong>{{ worlds.length }}</strong><small>{{ t('world.worldApi') }}</small></div><div class="metric-card"><span>{{ t('world.state') }}</span><strong class="state-value"><i class="live-dot" :class="{ paused: activeWorld?.status !== 'active' }"></i>{{ activeWorld?.status === 'active' ? t('world.running') : t('world.paused') }}</strong><small>{{ activeWorld?.level_id }} / {{ activeWorld?.kind }}</small></div><div class="metric-card"><span>{{ t('world.soup') }}</span><strong>{{ soupTotal }}</strong><small>{{ t('world.playerApi') }}</small></div></div><div class="dashboard-grid"><div class="scene-card"><div class="card-header"><div><span class="eyebrow">{{ t('labels.worldMap') }}</span><h3>{{ activeWorld.name }}</h3></div><span class="live-badge"><i class="live-dot"></i> {{ activeWorld.status.toUpperCase() }}</span></div><WorldScene /><div class="scene-footer"><span>{{ t('world.worldId') }} <b>{{ activeWorld.id }}</b></span><span>{{ t('world.level') }} <b>{{ activeWorld.level_id }}</b></span><span>{{ t('world.type') }} <b>{{ activeWorld.kind }}</b></span></div></div><div class="activity-card"><div class="card-header"><div><span class="eyebrow">{{ t('labels.playerData') }}</span><h3>{{ t('world.elements') }}</h3></div></div><div class="activity-list"><div v-for="item in wallet?.bio_soup || []" :key="item.element_id" class="activity-row"><span class="activity-icon cyan">{{ item.symbol }}</span><div><b>{{ item.name }}</b><small>{{ item.element_id }}</small></div><time>{{ item.amount }}</time></div></div></div></div></template></section></template>
